Object.freeze(GalaxyGame.Config);

window.GalaxyGame = window.GalaxyGame || {};
window.GalaxyGame.Utils = {};

GalaxyGame.Utils.clamp = function(value, min, max) {
    return Math.min(Math.max(value, min), max);
};

GalaxyGame.Utils.randomBetween = function(min, max) {
    return Math.random() * (max - min) + min;
};

GalaxyGame.Utils.randomIntBetween = function(min, max) {
    return Math.floor(GalaxyGame.Utils.randomBetween(min, max + 1));
};

GalaxyGame.Utils.lerp = function(a, b, t) {
    return a + (b - a) * t;
};

GalaxyGame.Utils.degToRad = function(degrees) {
    return degrees * (Math.PI / 180);
};

GalaxyGame.Utils.normalizeAngle = function(angle) {
    return ((angle % 360) + 360) % 360;
};

GalaxyGame.Utils.checkAABB = function(rectA, rectB) {
    return !(
        rectA.x + rectA.width  < rectB.x ||
        rectA.x                > rectB.x + rectB.width ||
        rectA.y + rectA.height < rectB.y ||
        rectA.y                > rectB.y + rectB.height
    );
};

GalaxyGame.Utils.getDistance = function(x1, y1, x2, y2) {
    return Math.hypot(x2 - x1, y2 - y1);
};

GalaxyGame.Utils.getAngleBetween = function(x1, y1, x2, y2) {
    return Math.atan2(y2 - y1, x2 - x1);
};

GalaxyGame.Utils.isOutOfBounds = function(x, y, width, height, canvasWidth, canvasHeight) {
    return x + width < 0 || x > canvasWidth || y + height < 0 || y > canvasHeight;
};

GalaxyGame.Utils.pickRandom = function(array) {
    return array[GalaxyGame.Utils.randomIntBetween(0, array.length - 1)];
};

window.GalaxyGame = window.GalaxyGame || {};
window.GalaxyGame.Audio = (function () {

    let audioCtx = null;
    let masterGain = null;
    let isMuted = false;

    function _initContext() {
        if (audioCtx) return;
        var AudioContextClass = window.AudioContext || window.webkitAudioContext;
        if (!AudioContextClass) return;
        audioCtx = new AudioContextClass();
        masterGain = audioCtx.createGain();
        masterGain.gain.value = 0.3;
        masterGain.connect(audioCtx.destination);
    }

    function _playTone(config) {
        if (isMuted) return;
        if (!audioCtx || !masterGain) return;

        var now = audioCtx.currentTime;
        var startTime = (config.startTime !== undefined) ? config.startTime : 0;
        var duration = config.duration;
        var gainPeak = config.gainPeak;

        var oscillator = audioCtx.createOscillator();
        var gainNode = audioCtx.createGain();

        oscillator.connect(gainNode);
        gainNode.connect(masterGain);

        oscillator.type = config.type;

        oscillator.frequency.setValueAtTime(config.frequency, now + startTime);

        if (config.endFrequency !== config.frequency) {
            oscillator.frequency.exponentialRampToValueAtTime(
                config.endFrequency,
                now + startTime + duration
            );
        }

        gainNode.gain.setValueAtTime(0, now + startTime);
        gainNode.gain.linearRampToValueAtTime(gainPeak, now + startTime + 0.01);
        gainNode.gain.exponentialRampToValueAtTime(0.001, now + startTime + duration);

        oscillator.start(now + startTime);
        oscillator.stop(now + startTime + duration + 0.05);
    }

    function playShoot() {
        _initContext();
        _playTone({
            type: 'square',
            frequency: 880,
            endFrequency: 220,
            duration: 0.12,
            gainPeak: 0.4,
            startTime: 0
        });
    }

    function playExplosion() {
        _initContext();
        _playTone({
            type: 'sawtooth',
            frequency: 150,
            endFrequency: 30,
            duration: 0.6,
            gainPeak: 0.6,
            startTime: 0
        });
        _playTone({
            type: 'square',
            frequency: 80,
            endFrequency: 20,
            duration: 0.8,
            gainPeak: 0.4,
            startTime: 0
        });
    }

    function playPowerUp() {
        _initContext();
        _playTone({
            type: 'sine',
            frequency: 440,
            endFrequency: 440,
            duration: 0.1,
            gainPeak: 0.5,
            startTime: 0
        });
        _playTone({
            type: 'sine',
            frequency: 554,
            endFrequency: 554,
            duration: 0.1,
            gainPeak: 0.5,
            startTime: 0.1
        });
        _playTone({
            type: 'sine',
            frequency: 659,
            endFrequency: 880,
            duration: 0.2,
            gainPeak: 0.6,
            startTime: 0.2
        });
    }

    function playLevelUp() {
        _initContext();
        _playTone({
            type: 'square',
            frequency: 523,
            endFrequency: 523,
            duration: 0.12,
            gainPeak: 0.5,
            startTime: 0.00
        });
        _playTone({
            type: 'square',
            frequency: 659,
            endFrequency: 659,
            duration: 0.12,
            gainPeak: 0.5,
            startTime: 0.13
        });
        _playTone({
            type: 'square',
            frequency: 784,
            endFrequency: 784,
            duration: 0.12,
            gainPeak: 0.5,
            startTime: 0.26
        });
        _playTone({
            type: 'square',
            frequency: 1047,
            endFrequency: 1047,
            duration: 0.25,
            gainPeak: 0.7,
            startTime: 0.39
        });
    }

    function playGameOver() {
        _initContext();
        _playTone({
            type: 'sawtooth',
            frequency: 440,
            endFrequency: 220,
            duration: 0.4,
            gainPeak: 0.6,
            startTime: 0.0
        });
        _playTone({
            type: 'sawtooth',
            frequency: 220,
            endFrequency: 110,
            duration: 0.4,
            gainPeak: 0.5,
            startTime: 0.4
        });
        _playTone({
            type: 'sawtooth',
            frequency: 110,
            endFrequency: 40,
            duration: 0.6,
            gainPeak: 0.4,
            startTime: 0.8
        });
    }

    function toggleMute() {
        isMuted = !isMuted;
        if (masterGain) {
            masterGain.gain.value = isMuted ? 0 : 0.3;
        }
        return isMuted;
    }

    function getMuteState() {
        return isMuted;
    }

    return {
        playShoot: playShoot,
        playExplosion: playExplosion,
        playPowerUp: playPowerUp,
        playLevelUp: playLevelUp,
        playGameOver: playGameOver,
        toggleMute: toggleMute,
        getMuteState: getMuteState
    };

})();

window.GalaxyGame = window.GalaxyGame || {};
window.GalaxyGame.Renderer = (function () {

    let _ctx    = null;
    let _canvas = null;

    function init(canvasElement) {
        _canvas = canvasElement;
        _ctx    = canvasElement.getContext('2d');
    }

    function _clearScreen() {
        _ctx.fillStyle = GalaxyGame.Config.CANVAS.BG_COLOR;
        _ctx.fillRect(0, 0, _canvas.width, _canvas.height);
    }

    function _drawStarfield(stars) {
        for (var i = 0; i < stars.length; i++) {
            var star = stars[i];
            _ctx.globalAlpha = star.opacity;
            _ctx.fillStyle   = '#FFFFFF';
            _ctx.beginPath();
            _ctx.arc(star.x, star.y, star.radius, 0, Math.PI * 2);
            _ctx.fill();
        }
        _ctx.globalAlpha = 1;
    }

    function _drawScanlines() {
        _ctx.fillStyle = 'rgba(0, 0, 0, 0.08)';
        for (var i = 0; i < _canvas.height; i += 4) {
            _ctx.fillRect(0, i, _canvas.width, 2);
        }
    }

    function _drawShip(ship) {
        _ctx.save();
        _ctx.translate(ship.x, ship.y);
        _ctx.rotate(ship.angle);

        _ctx.beginPath();
        _ctx.moveTo(0, -18);
        _ctx.lineTo(12, 12);
        _ctx.lineTo(-12, 12);
        _ctx.closePath();
        _ctx.fillStyle = GalaxyGame.Config.COLORS.NEON_CYAN;
        _ctx.fill();

        _ctx.fillStyle = GalaxyGame.Config.COLORS.NEON_BLUE;
        _ctx.fillRect(-4, -8, 8, 10);

        if (ship.isBoosted) {
            _ctx.globalAlpha = 0.8;
            _ctx.beginPath();
            _ctx.moveTo(-6, 14);
            _ctx.lineTo(6, 14);
            _ctx.lineTo(0, 26);
            _ctx.closePath();
            _ctx.fillStyle = '#FF6600';
            _ctx.fill();
            _ctx.globalAlpha = 1;
        }

        if (ship.isShielded) {
            _ctx.globalAlpha = 0.6;
            _ctx.beginPath();
            _ctx.arc(0, 0, 28, 0, Math.PI * 2);
            _ctx.strokeStyle = '#00FF88';
            _ctx.lineWidth   = 2;
            _ctx.stroke();
            _ctx.globalAlpha = 1;
        }

        _ctx.restore();
    }

    function _drawObstacle(obstacle) {
        _ctx.save();
        _ctx.translate(obstacle.x, obstacle.y);

        switch (obstacle.type) {

            case 'comet': {
                var tailLen = obstacle.radius * 3.5;
                var tailAngle = obstacle.angle + Math.PI;
                var grad = _ctx.createLinearGradient(0, 0,
                    Math.cos(tailAngle) * tailLen,
                    Math.sin(tailAngle) * tailLen);
                grad.addColorStop(0,   'rgba(255, 68, 68, 0.9)');
                grad.addColorStop(1,   'rgba(255, 68, 68, 0)');
                _ctx.beginPath();
                _ctx.moveTo(0, 0);
                _ctx.lineTo(
                    Math.cos(tailAngle) * tailLen,
                    Math.sin(tailAngle) * tailLen
                );
                _ctx.strokeStyle = grad;
                _ctx.lineWidth   = obstacle.radius * 0.8;
                _ctx.lineCap     = 'round';
                _ctx.stroke();

                _ctx.save();
                _ctx.rotate(obstacle.angle);
                _ctx.scale(1, 0.55);
                _ctx.beginPath();
                _ctx.arc(0, 0, obstacle.radius, 0, Math.PI * 2);
                _ctx.fillStyle = '#FF4444';
                _ctx.fill();
                _ctx.restore();
                break;
            }

            case 'asteroid': {
                var verts = obstacle.vertices;
                if (verts && verts.length) {
                    _ctx.beginPath();
                    _ctx.moveTo(verts[0].x, verts[0].y);
                    for (var v = 1; v < verts.length; v++) {
                        _ctx.lineTo(verts[v].x, verts[v].y);
                    }
                    _ctx.closePath();
                } else {
                    _ctx.beginPath();
                    _ctx.arc(0, 0, obstacle.radius, 0, Math.PI * 2);
                }
                _ctx.fillStyle   = '#888888';
                _ctx.fill();
                _ctx.strokeStyle = '#AAAAAA';
                _ctx.lineWidth   = 1;
                _ctx.stroke();
                break;
            }

            case 'planet': {
                var grad2 = _ctx.createRadialGradient(
                    -obstacle.radius * 0.3, -obstacle.radius * 0.3, obstacle.radius * 0.1,
                    0, 0, obstacle.radius
                );
                grad2.addColorStop(0,   _lightenColor(obstacle.color, 60));
                grad2.addColorStop(0.6, obstacle.color);
                grad2.addColorStop(1,   _darkenColor(obstacle.color, 60));

                _ctx.beginPath();
                _ctx.arc(0, 0, obstacle.radius, 0, Math.PI * 2);
                _ctx.fillStyle = grad2;
                _ctx.fill();

                if (obstacle.radius > 35) {
                    _ctx.save();
                    _ctx.scale(1, 0.3);
                    _ctx.beginPath();
                    _ctx.arc(0, 0, obstacle.radius * 1.5, 0, Math.PI * 2);
                    _ctx.strokeStyle = 'rgba(255,255,255,0.25)';
                    _ctx.lineWidth   = 4;
                    _ctx.stroke();
                    _ctx.beginPath();
                    _ctx.arc(0, 0, obstacle.radius * 1.75, 0, Math.PI * 2);
                    _ctx.strokeStyle = 'rgba(255,255,255,0.12)';
                    _ctx.lineWidth   = 3;
                    _ctx.stroke();
                    _ctx.restore();
                }
                break;
            }

            case 'ufo': {
                var bodyH = obstacle.radius * 0.55;

                _ctx.save();
                _ctx.scale(1, 0.55);
                _ctx.beginPath();
                _ctx.arc(0, 0, obstacle.radius, 0, Math.PI * 2);
                _ctx.fillStyle   = '#CC00FF';
                _ctx.fill();
                _ctx.strokeStyle = '#FF88FF';
                _ctx.lineWidth   = 1.5;
                _ctx.stroke();
                _ctx.restore();

                _ctx.beginPath();
                _ctx.arc(0, -bodyH * 0.5, obstacle.radius * 0.55, Math.PI, 0);
                _ctx.closePath();
                _ctx.fillStyle   = '#FF00FF';
                _ctx.fill();
                _ctx.strokeStyle = '#FF88FF';
                _ctx.lineWidth   = 1;
                _ctx.stroke();

                var numLights = 5;
                for (var l = 0; l < numLights; l++) {
                    var lAngle = (l / numLights) * Math.PI * 2;
                    var lx = Math.cos(lAngle) * obstacle.radius * 0.75;
                    var ly = Math.sin(lAngle) * obstacle.radius * 0.28;
                    _ctx.beginPath();
                    _ctx.arc(lx, ly, 2.5, 0, Math.PI * 2);
                    _ctx.fillStyle = (l % 2 === 0) ? '#FFFF00' : '#00FFFF';
                    _ctx.fill();
                }
                break;
            }

            case 'meteorite':
            case 'meteor': {
                _ctx.beginPath();
                _ctx.arc(0, 0, obstacle.radius, 0, Math.PI * 2);
                _ctx.fillStyle = '#FF8800';
                _ctx.fill();
                _ctx.beginPath();
                _ctx.arc(-obstacle.radius * 0.25, -obstacle.radius * 0.25,
                         obstacle.radius * 0.35, 0, Math.PI * 2);
                _ctx.fillStyle = 'rgba(255,200,100,0.5)';
                _ctx.fill();
                break;
            }

            default:
                break;
        }

        _ctx.restore();
    }

    function _drawPowerUp(powerUp) {
        _ctx.save();
        _ctx.translate(powerUp.x, powerUp.y);

        _ctx.globalAlpha = 0.3 + 0.2 * Math.sin(Date.now() * 0.005);
        _ctx.beginPath();
        _ctx.arc(0, 0, powerUp.radius * 1.8, 0, Math.PI * 2);
        _ctx.fillStyle = powerUp.color;
        _ctx.fill();
        _ctx.globalAlpha = 1;

        _ctx.beginPath();
        _ctx.arc(0, 0, powerUp.radius, 0, Math.PI * 2);
        _ctx.fillStyle = powerUp.color;
        _ctx.fill();
        _ctx.strokeStyle = '#FFFFFF';
        _ctx.lineWidth   = 1.5;
        _ctx.stroke();

        _ctx.fillStyle    = '#000000';
        _ctx.font         = 'bold ' + (powerUp.radius * 1.1) + 'px monospace';
        _ctx.textAlign    = 'center';
        _ctx.textBaseline = 'middle';

        var icon = '?';
        if (powerUp.type === 'shield') icon = 'S';
        if (powerUp.type === 'turbo')  icon = 'T';
        if (powerUp.type === 'magnet') icon = 'M';
        _ctx.fillText(icon, 0, 1);

        _ctx.restore();
    }

    function _drawParticles(particles) {
        for (var i = 0; i < particles.length; i++) {
            var p = particles[i];
            _ctx.save();
            _ctx.globalAlpha = p.alpha !== undefined ? p.alpha : (p.opacity !== undefined ? p.opacity : 1);
            _ctx.fillStyle   = p.color;
            _ctx.beginPath();
            _ctx.arc(p.x, p.y, p.radius, 0, Math.PI * 2);
            _ctx.fill();
            _ctx.restore();
        }
    }

    function _drawLevelUpBanner(levelName) {
        _ctx.save();
        _ctx.globalAlpha = 0.85;
        _ctx.fillStyle   = 'rgba(0, 0, 0, 0.6)';
        _ctx.fillRect(0, _canvas.height / 2 - 40, _canvas.width, 80);
        _ctx.globalAlpha = 1;

        _ctx.font         = '20px "Press Start 2P", monospace';
        _ctx.textAlign    = 'center';
        _ctx.textBaseline = 'middle';
        _ctx.fillStyle    = GalaxyGame.Config.COLORS.NEON_YELLOW;
        _ctx.fillText('NIVEL: ' + levelName, _canvas.width / 2, _canvas.height / 2);
        _ctx.restore();
    }

    function _lightenColor(hex, amount) {
        return _shiftColor(hex, amount);
    }

    function _darkenColor(hex, amount) {
        return _shiftColor(hex, -amount);
    }

    function _shiftColor(hex, amount) {
        var num = parseInt(hex.replace('#', ''), 16);
        var r   = Math.min(255, Math.max(0, (num >> 16) + amount));
        var g   = Math.min(255, Math.max(0, ((num >> 8) & 0x00FF) + amount));
        var b   = Math.min(255, Math.max(0, (num & 0x0000FF) + amount));
        return '#' +
            ('00' + r.toString(16)).slice(-2) +
            ('00' + g.toString(16)).slice(-2) +
            ('00' + b.toString(16)).slice(-2);
    }

    function drawFrame(gameState) {
        if (!_ctx) return;

        _clearScreen();

        if (gameState.stars && gameState.stars.length) {
            _drawStarfield(gameState.stars);
        }

        if (gameState.powerUps) {
            for (var p = 0; p < gameState.powerUps.length; p++) {
                _drawPowerUp(gameState.powerUps[p]);
            }
        }

        if (gameState.obstacles) {
            for (var o = 0; o < gameState.obstacles.length; o++) {
                _drawObstacle(gameState.obstacles[o]);
            }
        }

        if (gameState.ship) {
            _drawShip(gameState.ship);
        }

        if (gameState.particles) {
            _drawParticles(gameState.particles);
        }

        if (gameState.levelUpBanner) {
            _drawLevelUpBanner(gameState.levelUpBanner);
        }

        _drawScanlines();
    }

    return {
        init:              init,
        drawFrame:         drawFrame,
        drawLevelUpBanner: _drawLevelUpBanner
    };

})();

window.GalaxyGame = window.GalaxyGame || {};
window.GalaxyGame.Entities = {};

// ─────────────────────────────────────────────
// SHIP
// ─────────────────────────────────────────────
GalaxyGame.Entities.Ship = function(x, y) {
    var cfg = GalaxyGame.Config;
    this.x = x;
    this.y = y;
    this.angle = -Math.PI / 2;
    this.velocityX = 0;
    this.velocityY = 0;
    this.speed = 0;
    this.lives = 3;
    this.isInvulnerable = false;
    this.invulnerableTimer = 0;
    this.activePowerUp = null;
    this.powerUpTimer = 0;
    this.width = cfg.PLAYER.WIDTH;
    this.height = cfg.PLAYER.HEIGHT;
};

GalaxyGame.Entities.Ship.prototype.update = function(deltaTime, inputState, hasTurbo) {
    var cfg = GalaxyGame.Config;
    var ROTATION_SPEED = cfg.PLAYER.ROTATION_SPEED;
    var ACCELERATION    = cfg.PLAYER.ACCELERATION;
    var DECELERATION    = cfg.PLAYER.DECELERATION;
    var MAX_SPEED       = cfg.PLAYER.MAX_SPEED;
    var MIN_SPEED       = cfg.PLAYER.MIN_SPEED;
    var TURBO_MULT      = cfg.PLAYER.TURBO_MULTIPLIER;
    var CW              = cfg.CANVAS.WIDTH;
    var CH              = cfg.CANVAS.HEIGHT;

    // 1. Rotación
    if (inputState.left) {
        this.angle -= ROTATION_SPEED * deltaTime;
    }
    if (inputState.right) {
        this.angle += ROTATION_SPEED * deltaTime;
    }

    // 2. Aceleración
    if (inputState.up) {
        this.speed += ACCELERATION * deltaTime;
        var maxSpeed = (hasTurbo || this.activePowerUp === 'turbo')
            ? MAX_SPEED * TURBO_MULT
            : MAX_SPEED;
        this.speed = Math.min(this.speed, maxSpeed);
    }

    // 3. Frenado
    if (inputState.down) {
        this.speed -= DECELERATION * deltaTime;
        this.speed = Math.max(this.speed, MIN_SPEED);
    }

    // 4. Fricción pasiva
    if (!inputState.up && !inputState.down) {
        this.speed *= (1 - 0.05 * deltaTime);
        this.speed = Math.max(this.speed, 0);
    }

    // 5. Actualizar velocidad vectorial
    this.velocityX = Math.cos(this.angle) * this.speed;
    this.velocityY = Math.sin(this.angle) * this.speed;

    // 6. Mover posición
    this.x += this.velocityX * deltaTime;
    this.y += this.velocityY * deltaTime;

    // 7. Wrap de pantalla
    if (this.x < 0)  { this.x = CW; }
    if (this.x > CW) { this.x = 0; }
    if (this.y < 0)  { this.y = CH; }
    if (this.y > CH) { this.y = 0; }

    // 8. Decrementar timers
    if (this.invulnerableTimer > 0) {
        this.invulnerableTimer -= deltaTime;
        if (this.invulnerableTimer <= 0) {
            this.isInvulnerable = false;
            this.invulnerableTimer = 0;
        }
    }

    if (this.powerUpTimer > 0) {
        this.powerUpTimer -= deltaTime;
        if (this.powerUpTimer <= 0) {
            this.activePowerUp = null;
            this.powerUpTimer = 0;
        }
    }
};

GalaxyGame.Entities.Ship.prototype.takeDamage = function() {
    if (this.isInvulnerable) { return; }
    if (this.activePowerUp === 'shield') { return; }
    this.lives -= 1;
    this.isInvulnerable = true;
    this.invulnerableTimer = GalaxyGame.Config.PLAYER.INVINCIBILITY_FRAMES / 60;
};

GalaxyGame.Entities.Ship.prototype.applyPowerUp = function(type, duration) {
    this.activePowerUp = type;
    this.powerUpTimer = duration;
    if (type === 'shield') {
        this.isInvulnerable = true;
        this.invulnerableTimer = duration;
    }
};

// ─────────────────────────────────────────────
// OBSTACLE
// ─────────────────────────────────────────────
GalaxyGame.Entities.Obstacle = function(type, x, y, speedMultiplier) {
    var cfg = GalaxyGame.Config;
    var obsCfg = cfg.OBSTACLES;

    this.type = type;
    this.x = x;
    this.y = y;
    this.active = true;

    var typeCfg;
    if (type === 'comet')     { typeCfg = obsCfg.COMET; }
    else if (type === 'asteroid')  { typeCfg = obsCfg.ASTEROID; }
    else if (type === 'planet')    { typeCfg = obsCfg.PLANET; }
    else if (type === 'ufo')       { typeCfg = obsCfg.UFO; }
    else if (type === 'meteorite') { typeCfg = obsCfg.METEORITE; }
    else                           { typeCfg = obsCfg.ASTEROID; }

    this.radius = (typeCfg.width / 2);
    this.width  = typeCfg.width;
    this.height = typeCfg.height;
    this.points = typeCfg.points;
    this.color  = typeCfg.color;

    if (type === 'ufo') {
        this.angle = 0;
    } else {
        this.angle = GalaxyGame.Utils.randomBetween(0, Math.PI * 2);
    }

    var baseSpeed = typeCfg.baseSpeed * (speedMultiplier || 1);

    if (type === 'comet') {
        this.velocityX = Math.cos(this.angle) * baseSpeed * 1.8;
        this.velocityY = Math.sin(this.angle) * baseSpeed * 1.8;
    } else if (type === 'asteroid') {
        this.velocityX = GalaxyGame.Utils.randomBetween(-baseSpeed, baseSpeed);
        this.velocityY = GalaxyGame.Utils.randomBetween(-baseSpeed, baseSpeed);
    } else if (type === 'planet') {
        this.velocityX = Math.cos(this.angle) * baseSpeed * 0.4;
        this.velocityY = Math.sin(this.angle) * baseSpeed * 0.4;
    } else if (type === 'ufo') {
        this.velocityX = Math.cos(this.angle) * baseSpeed;
        this.velocityY = Math.sin(this.angle) * baseSpeed;
    } else if (type === 'meteorite') {
        this.velocityX = GalaxyGame.Utils.randomBetween(-baseSpeed, baseSpeed) * 1.2;
        this.velocityY = GalaxyGame.Utils.randomBetween(-baseSpeed, baseSpeed) * 1.2;
    } else {
        this.velocityX = Math.cos(this.angle) * baseSpeed;
        this.velocityY = Math.sin(this.angle) * baseSpeed;
    }
};

GalaxyGame.Entities.Obstacle.prototype.update = function(deltaTime, shipX, shipY) {
    var CW = GalaxyGame.Config.CANVAS.WIDTH;
    var CH = GalaxyGame.Config.CANVAS.HEIGHT;

    if (this.type === 'ufo') {
        var dx = shipX - this.x;
        var dy = shipY - this.y;
        var dist = Math.sqrt(dx * dx + dy * dy);
        if (dist > 0) {
            var ufoSpeed = Math.sqrt(
                this.velocityX * this.velocityX + this.velocityY * this.velocityY
            );
            if (ufoSpeed === 0) {
                ufoSpeed = GalaxyGame.Config.OBSTACLES.UFO.baseSpeed;
            }
            this.velocityX = (dx / dist) * ufoSpeed;
            this.velocityY = (dy / dist) * ufoSpeed;
        }
    }

    this.x += this.velocityX * deltaTime;
    this.y += this.velocityY * deltaTime;

    var margin = this.radius;
    if (this.x < -margin)        { this.x = CW + margin; }
    if (this.x > CW + margin)    { this.x = -margin; }
    if (this.y < -margin)        { this.y = CH + margin; }
    if (this.y > CH + margin)    { this.y = -margin; }
};

// ─────────────────────────────────────────────
// POWERUP
// ─────────────────────────────────────────────
GalaxyGame.Entities.PowerUp = function(type, x, y) {
    var cfg = GalaxyGame.Config;
    var puCfg;
    if (type === 'shield')      { puCfg = cfg.POWERUPS.SHIELD; }
    else if (type === 'turbo')  { puCfg = cfg.POWERUPS.TURBO; }
    else if (type === 'magnet') { puCfg = cfg.POWERUPS.MAGNET; }
    else                        { puCfg = cfg.POWERUPS.SHIELD; }

    this.type = type;
    this.x = x;
    this.y = y;
    this.active = true;
    this.radius = 14;
    this.width  = this.radius * 2;
    this.height = this.radius * 2;
    this.duration = puCfg.durationFrames / 60;
    this.color = puCfg.color;
    this.angle = 0;
    this.floatTimer = 0;
    this.floatAmplitude = 4;
    this.floatSpeed = 2;
    this.baseY = y;
};

GalaxyGame.Entities.PowerUp.prototype.update = function(deltaTime) {
    this.floatTimer += deltaTime;
    this.y = this.baseY + Math.sin(this.floatTimer * this.floatSpeed) * this.floatAmplitude;
    this.angle += 1.5 * deltaTime;
};

// ─────────────────────────────────────────────
// PARTICLE
// ─────────────────────────────────────────────
GalaxyGame.Entities.Particle = function(x, y, velocityX, velocityY, color, life, radius) {
    this.x = x;
    this.y = y;
    this.velocityX = velocityX;
    this.velocityY = velocityY;
    this.color = color;
    this.life = life;
    this.maxLife = life;
    this.radius = radius !== undefined ? radius : 2;
    this.active = true;
};

GalaxyGame.Entities.Particle.prototype.update = function(deltaTime) {
    this.x += this.velocityX * deltaTime;
    this.y += this.velocityY * deltaTime;
    this.life -= deltaTime;
    this.velocityX *= (1 - 0.8 * deltaTime);
    this.velocityY *= (1 - 0.8 * deltaTime);
    if (this.life <= 0) {
        this.active = false;
        this.life = 0;
    }
};

Object.defineProperty(GalaxyGame.Entities.Particle.prototype, 'alpha', {
    get: function() {
        return this.maxLife > 0 ? Math.max(0, this.life / this.maxLife) : 0;
    }
});

