  height: 100%;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 20px;
  z-index: 20;
}

/* Pantalla de inicio — fondo semitransparente sobre el canvas */
#screen-start {
  background-color: rgba(0, 0, 0, 0.88);
}

/* Pantalla de pausa — fondo más oscuro para indicar pausa */
#screen-pause {
  background-color: rgba(0, 0, 0, 0.82);
}

/* Pantalla de game-over */
#screen-gameover {
  background-color: rgba(0, 0, 0, 0.88);
}

/* ============================================================
   PASO 9 — Títulos de pantalla
   ============================================================ */
#start-title {
  font-size: var(--title-font-size);
  color: var(--color-neon-cyan);
  text-align: center;
  text-shadow:
    0 0 8px var(--color-neon-cyan),
    0 0 24px rgba(0, 255, 255, 0.5);
  letter-spacing: 2px;
  line-height: 1.4;
}

#pause-title {
  font-size: 22px;
  color: var(--color-neon-yellow);
  text-align: center;
  text-shadow:
    0 0 8px var(--color-neon-yellow),
    0 0 20px rgba(255, 230, 0, 0.4);
  letter-spacing: 2px;
}

#gameover-title {
  font-size: 24px;
  color: var(--color-neon-pink);
  text-align: center;
  text-shadow:
    0 0 8px var(--color-neon-pink),
    0 0 24px rgba(255, 0, 255, 0.5);
  letter-spacing: 2px;
}

/* ============================================================
   PASO 10 — Subtítulo de pantalla de inicio
   ============================================================ */
#start-subtitle {
  font-size: var(--subtitle-font-size);
  color: var(--color-text-dim);
  text-align: center;
  letter-spacing: 1px;
}

/* ============================================================
   PASO 11 — Selector de dificultad
   ============================================================ */
#start-difficulty {
  display: flex;
  flex-direction: row;
  align-items: center;
  justify-content: center;
  gap: 12px;
}

/* Botones de dificultad */
.btn-difficulty {
  font-family: var(--font-arcade);
  font-size: var(--btn-font-size);
  color: var(--color-text-primary);
  background-color: transparent;
  border: 1px solid var(--color-btn-border);
  padding: 8px 14px;
  cursor: pointer;
  text-transform: uppercase;
  letter-spacing: 1px;
  transition:
    background-color var(--transition-fast),
    color var(--transition-fast),
    box-shadow var(--transition-fast);
  outline: none;
}

.btn-difficulty:hover {
  background-color: var(--color-btn-hover-bg);
  box-shadow: 0 0 8px rgba(0, 255, 255, 0.3);
}

.btn-difficulty.is-active {
  background-color: var(--color-btn-active-bg);
  color: var(--color-neon-cyan);
  box-shadow:
    0 0 0 1px var(--color-neon-cyan),
    0 0 12px rgba(0, 255, 255, 0.4);
}

/* ============================================================
   PASO 12 — Botones de acción principales
   ============================================================ */
#btn-start,
#btn-resume,
#btn-quit-pause,
#btn-restart,
#btn-quit-gameover {
  font-family: var(--font-arcade);
  font-size: var(--btn-font-size);
  color: var(--color-neon-cyan);
  background-color: transparent;
  border: 2px solid var(--color-neon-cyan);
  padding: 12px 24px;
  cursor: pointer;
  text-transform: uppercase;
  letter-spacing: 2px;
  transition:
    background-color var(--transition-fast),
    box-shadow var(--transition-fast),
    transform var(--transition-fast);
  outline: none;
}

#btn-start:hover,
#btn-resume:hover,
#btn-restart:hover {
  background-color: var(--color-btn-hover-bg);
  box-shadow:
    0 0 12px rgba(0, 255, 255, 0.5),
    0 0 24px rgba(0, 255, 255, 0.2);
  transform: scale(1.04);
}

#btn-start:active,
#btn-resume:active,
#btn-restart:active {
  background-color: var(--color-btn-active-bg);
  transform: scale(0.97);
}

/* Botones de salir — acento en naranja/rosa para distinguirlos */
#btn-quit-pause,
#btn-quit-gameover {
  color: var(--color-neon-orange);
  border-color: var(--color-neon-orange);
  font-size: 9px;
  padding: 8px 18px;
}

#btn-quit-pause:hover,
#btn-quit-gameover:hover {
  background-color: rgba(255, 102, 0, 0.15);
  box-shadow:
    0 0 10px rgba(255, 102, 0, 0.4),
    0 0 20px rgba(255, 102, 0, 0.15);
  transform: scale(1.04);
}

#btn-quit-pause:active,
#btn-quit-gameover:active {
  background-color: rgba(255, 102, 0, 0.3);
  transform: scale(0.97);
}

/* ============================================================
   PASO 13 — Hint de controles en pantalla de inicio
   ============================================================ */
#start-controls-hint {
  font-size: 8px;
  color: var(--color-text-dim);
  text-align: center;
  line-height: 2;
  letter-spacing: 1px;
}

/* ============================================================
   PASO 14 — Bloque de high score en pantalla de inicio
   ============================================================ */
#start-highscore {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 6px;
}

#start-highscore-value {
  font-size: 14px;
  color: var(--color-neon-green);
  text-shadow:
    0 0 6px var(--color-neon-green),
    0 0 16px rgba(57, 255, 20, 0.35);
}

/* ============================================================
   PASO 15 — Bloques de puntuación en pantalla de game-over
   ============================================================ */
#gameover-score,
#gameover-highscore {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 6px;
}

#gameover-score-value {
  font-size: 16px;
  color: var(--color-neon-cyan);
  text-shadow:
    0 0 6px var(--color-neon-cyan),
    0 0 16px rgba(0, 255, 255, 0.35);
}

#gameover-highscore-value {
  font-size: 14px;
  color: var(--color-neon-green);
  text-shadow:
    0 0 6px var(--color-neon-green),
    0 0 16px rgba(57, 255, 20, 0.35);
}

/* ============================================================
   PASO 16 — Estados visuales is-* sobre #game-canvas-wrapper
   ============================================================ */

/* Estado: juego en ejecución — sin cambio visual extra, el canvas lo gestiona */
#game-canvas-wrapper.is-running {
  /* Estado base, sin overlay adicional */
}

/* Estado: pausa — leve tinte sobre el wrapper */
#game-canvas-wrapper.is-paused {
  box-shadow:
    0 0 0 2px var(--color-neon-yellow),
    0 0 24px 4px rgba(255, 230, 0, 0.25);
}

/* Estado: game-over — tinte rojo/rosa */
#game-canvas-wrapper.is-gameover {
  box-shadow:
    0 0 0 2px var(--color-neon-pink),
    0 0 24px 4px rgba(255, 0, 255, 0.3);
}

/* Estado: nave con escudo activo */
#game-canvas-wrapper.is-shielded #game-canvas {
  filter: drop-shadow(0 0 6px var(--color-neon-cyan));
}

/* Estado: nave con turbo activo */
#game-canvas-wrapper.is-boosted #game-canvas {
  filter: drop-shadow(0 0 6px var(--color-neon-orange));
}

/* Estado: transición de nivel */
#game-canvas-wrapper.is-level-up {
  box-shadow:
    0 0 0 2px var(--color-neon-green),
    0 0 32px 8px rgba(57, 255, 20, 0.35);
}

/* ============================================================
   PASO 17 — Animación de parpadeo arcade (.is-flashing)
   ============================================================ */
@keyframes arcade-flash {
  0%,  100% { opacity: 1; }
  50%        { opacity: 0; }
}

.is-flashing {
  animation: arcade-flash 0.5s step-end infinite;
}

/* ============================================================
   PASO 18 — Animación de entrada para títulos (neón pulse)
   ============================================================ */
@keyframes neon-pulse {
  0%,  100% { opacity: 1;   text-shadow: 0 0 8px var(--color-neon-cyan), 0 0 24px rgba(0, 255, 255, 0.5); }
  50%        { opacity: 0.8; text-shadow: 0 0 16px var(--color-neon-cyan), 0 0 40px rgba(0, 255, 255, 0.7); }
}

#start-title {
  animation: neon-pulse 2.4s ease-in-out infinite;
}

/* ============================================================
   PASO 19 — Responsive: único bloque @media con transform:scale()
   ============================================================ */
@media (max-width: 840px), (max-height: 640px) {
  #game-canvas-wrapper {
    transform-origin: center center;
    transform: scale(
      min(
        calc((100vw - 16px) / 800),
        calc((100vh - 16px) / 600)
      )
    );
  }
}
